probe85.script:
import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { pathToFileURL } from "node:url";

const moduleUrl = (path, source, overrides = {}) => "data:text/javascript;base64," + Buffer.from(source.replace(/from "(\.[^"]+)"/g, (_, relative) => {
  const target = resolve(dirname(path), relative);
  return "from " + JSON.stringify(overrides[target] ?? pathToFileURL(target).href);
})).toString("base64");
const path = resolve("tests/helpers/php-structured-callable-faults.mjs");
let helper = await readFile(path, "utf8");
const original = 'const result = await runCopied(environment.LEAN_BRIDGE_PHP, [...installed.php.runtimeOptions,';
assert.equal(helper.split(original).length, 2);
helper = helper.replace(original, 'const result = await runCopied("/app/.toolchains/php-8.5.10-ffi/bin/php", ["-n", "-d", "extension=/app/.toolchains/php-8.5.10-ffi/lib/php/extensions/no-debug-non-zts-20250925/ffi.so", "-d", "ffi.enable=1",');
helper = helper.replace('assert.equal(result.stderr, ""); const report = JSON.parse(result.stdout);', 'process.stderr.write("PROBE_STDOUT_BEGIN\\n" + result.stdout.slice(0, 12000) + "\\nPROBE_STDOUT_END\\n"); assert.equal(result.stderr, ""); const report = JSON.parse(result.stdout);');
process.env.LEAN_BRIDGE_PHP_STRUCTURED_CALLABLE_TEST = "1";
process.env.LEAN_BRIDGE_PHP = "/usr/bin/php";
const testPath = resolve("tests/php-structured-callables.test.mjs");
await import(moduleUrl(testPath, await readFile(testPath, "utf8"), { [path]: moduleUrl(path, helper) }));

